("oh","عروضُنا الخاصّة.. بأسعارٍ تبدأُ من أربعينَ ألفَ دينار.","-1%","+2Hz"),("k0","فحصُ البشرة،","-2%","+1Hz"),("k1","العظامُ والمفاصل،","-1%","+2Hz"),("k2","تساقطُ الشعر،","-2%","+0Hz"),("k3","النسيانُ وعدمُ التركيز،","+0%","+1Hz"),("k4","والتحليلُ الشامل.","-4%","-1Hz"),("o0","برنامجُ فحصِ البشرة.. بأربعينَ ألفَ دينار.","-1%","+1Hz"),("o1","باقةُ العظامِ والمفاصل.. بأربعينَ ألفاً.","+0%","+0Hz"),
("o2","برنامجُ فحصِ تساقطِ الشعر.. بأربعينَ ألفاً.","+0%","+2Hz"),("o3","فحصُ النسيانِ وعدمِ التركيز.. بخمسةٍ وأربعينَ ألفاً.","+1%","+1Hz"),("o4","وعرضُ التحليلِ الشامل.. بخمسينَ ألفَ دينار.","-3%","-1Hz"),
("h1","خدمةُ السحبِ المنزليّ متوفّرة..","-3%","+2Hz"),("h2","كادرٌ متخصّص يصلُك أينما كنت.","-1%","+0Hz"),("p1","للحجزِ والاستفسار..","-4%","+2Hz"),
("p2","صفر سبعة سبعة صفر صفر، ثمانية أربعة ستّة، ثمانية تسعة ثمانية.","+2%","+0Hz"),
("c17b","مقابلَ مستشفى التوفيقِ الأهلي..","-3%","+0Hz"),("c17c","بجوارِ صيدليّةِ اليرموك.","-3%","-1Hz"),("c18b","مختبرُ النورِ الطبّي..","-5%","+2Hz"),
("c3","مختبرُ النورِ الجانبي..","-5%","+2Hz"),("c4","للتحليلاتِ المرضيّة.","-2%","-1Hz"),
("m0","سحبُ العيّناتِ بأمان،","+0%","+1Hz"),("m1","تعقيمٌ وسلامة،","-2%","+0Hz"),("m2","تجهيزُ العيّنات،","+0%","+2Hz"),
