os.makedirs('vo2',exist_ok=True)
dur={}
for i,t,r,p in CL:
  mp=f'vo2/{i}.mp3';wav=f'vo2/{i}.wav'
  if not os.path.exists(mp): subprocess.run(['python3','work/tts.py',t,mp,r,p,V],check=True)
  subprocess.run(['ffmpeg','-v','error','-y','-i',mp,'-af','silenceremove=start_periods=1:start_threshold=-48dB,areverse,silenceremove=start_periods=1:start_threshold=-48dB,areverse','-ar','44100','-ac','1',wav],check=True)
  dur[i]=float(subprocess.run(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0',wav],capture_output=True,text=True).stdout)
json.dump(dur,open('vo2/dur.json','w'),indent=0);print(dur)
